from pathlib import Path
import json
R=Path(__file__).resolve().parent
OLD=R.parents[1]/'cpp_tour'
OUT=R/'overlays';OUT.mkdir(parents=True,exist_ok=True)
def f(t,p,s,e):return dict(text=t,refs=[dict(source='T',section=s,pages=p if isinstance(p,list) else [p])],evidence=e)
def term(t,d):return dict(term=t,definition=d)
def row(t,d):return [f(t,d['refs'][0]['pages'],d['refs'][0]['section'],d['evidence']),d]
def save(n,terms,summary,qs,defs,rows,title='원문 비교',notes=None):
 old=json.loads((OLD/f'chapters/{n:02}.json').read_text('utf-8-sig'))
 x=dict(chapter=n,title=old['title'],source_code='T',learning=[terms[0]['definition'],terms[-1]['definition']],terms=terms,
 summary_basis=old['sections'][-1]['number']+' '+old['sections'][-1]['title'],summary=summary,
 review=[dict(question=q,answer=a) for q,a in qs],
 cheat=dict(definitions=defs,comparison_title=title,comparison_headers=['구분','책의 설명'],comparison_rows=rows,formulas=[]),
 checked_images=[],editor_notes=notes or [],corrections=[])
 def walk(v):
  if isinstance(v,dict):
   if 'refs'in v:
    for ref in v['refs']:yield from ref['pages']
   for w in v.values():yield from walk(w)
  elif isinstance(v,list):
   for w in v:yield from walk(w)
 if n==1:
  before=old['sections'][7]['blocks'][0]['text']
  after=before.replace('또는 enum class의 이름은','또는 enum class 안에서 정의한 이름은')
  x['corrections']=[dict(path=['sections',7,'blocks',0,'text'],before=before,after=after,refs=[dict(source='T',section='1.5 스코프와 수명',pages=[30])],reason='인쇄 p.31은 enum class 자체의 이름이 아니라 enum class 안에서 정의한 이름을 멤버 이름으로 설명한다. 생략으로 주체가 모호해진 기존 문구를 원문대로 명확히 한다.')]
 x['checked_images']=sorted(set(walk(x)))
 (OUT/f'{n:02}.json').write_text(json.dumps(x,ensure_ascii=False,indent=2),'utf-8')
 print(n,x['title'],x['checked_images'])

